package com.axion.mlbb.engine`n`nobject WinProbabilityEngine {`n    fun estimateWinProbability(playerTeamNetWorth: Int, enemyTeamNetWorth: Int, lordKilledByPlayer: Boolean): Double {`n    val netWorthDiff = playerTeamNetWorth - enemyTeamNetWorth`n        var baseProbability = 0.5 + (netWorthDiff / 50000.0)`n        if (lordKilledByPlayer) baseProbability += 0.15`n        return maxOf(0.05, minOf(0.95, baseProbability))`n    }`n}
